	private static final byte ROW_ENCODING_VERSION = 1;
	private static final byte UNBOUND = 0;
	private static final byte BOUND = 1;
	private static final byte IRI_VALUE = 2;
	private static final byte BNODE_VALUE = 3;
	private static final byte LITERAL_VALUE = 4;
	private static final byte TRIPLE_TERM_VALUE = 5;
